<script setup lang="ts">
import { computed, onMounted, reactive, ref, watch } from 'vue'
import type { FcQuiebre, FcQuiebrePayload, FcQuiebreResponse, NivelQuiebre } from '../interfaces/fc-quiebre.interface'
import { cambiarEstadoQuiebreFlujoCaja, guardarQuiebreFlujoCaja, listarQuiebresFlujoCaja, obtenerQuiebreFlujoCaja } from '../services/fc-quiebre'
const empty = (): FcQuiebreResponse => ({ quiebres: [], padres: [] }), blank = (): FcQuiebrePayload => ({ padre_id: null, nivel: 1, codigo: '', nombre: '', tipo_movimiento: '', orden: 0 })
const data = ref(empty()), search = ref(''), level = ref(''), loading = ref(false), error = ref(''), success = ref(''), showForm = ref(false), editing = ref<number | null>(null)
const form = reactive(blank())
const filtered = computed(() => { const q = search.value.toLocaleUpperCase(); return data.value.quiebres.filter(x => (!q || `${x.codigo} ${x.nombre} ${x.padre?.nombre || ''}`.toLocaleUpperCase().includes(q)) && (!level.value || x.nivel === Number(level.value))) })
const availableParents = computed(() => data.value.padres.filter(x => x.nivel === form.nivel - 1 && x.id !== editing.value))
const message = (e: unknown) => e instanceof Error ? e.message : 'No se pudo completar la operación.'
async function load() { loading.value = true; error.value = ''; try { data.value = await listarQuiebresFlujoCaja() } catch (e) { error.value = message(e) } finally { loading.value = false } }
function create() { editing.value = null; Object.assign(form, blank()); showForm.value = true }
async function edit(item: FcQuiebre) { loading.value = true; try { const x = await obtenerQuiebreFlujoCaja(item.id); editing.value = x.id; Object.assign(form, { padre_id: x.padre_id || null, nivel: x.nivel, codigo: x.codigo, nombre: x.nombre, tipo_movimiento: x.tipo_movimiento || '', orden: x.orden }); showForm.value = true } catch (e) { error.value = message(e) } finally { loading.value = false } }
async function save() { if (form.nivel > 1 && !form.padre_id) { error.value = `Debe seleccionar un quiebre padre de nivel ${form.nivel - 1}.`; return } loading.value = true; error.value = ''; try { await guardarQuiebreFlujoCaja(editing.value, { ...form }); success.value = `Quiebre ${editing.value ? 'actualizado' : 'registrado'} correctamente.`; showForm.value = false; await load() } catch (e) { error.value = message(e) } finally { loading.value = false } }
async function toggle(item: FcQuiebre) { const action = item.activo ? 'inactivar' : 'activar'; if (!confirm(`¿Desea ${action} ${item.nombre}?`)) return; loading.value = true; try { await cambiarEstadoQuiebreFlujoCaja(item.id); success.value = `Quiebre ${item.activo ? 'inactivado' : 'activado'} correctamente.`; await load() } catch (e) { error.value = message(e) } finally { loading.value = false } }
watch(() => form.nivel, () => { if (!availableParents.value.some(x => x.id === form.padre_id)) form.padre_id = null })
onMounted(load)
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / Administración / Finanzas / Quiebres de flujo de caja</nav><header class="hero"><div class="mark">QB</div><div><small>MIA · FINANZAS · FLUJO DE CAJA</small><h1>Quiebres de flujo de caja</h1><p>Estructura jerárquica de tres niveles para clasificar el flujo financiero.</p></div><strong>{{filtered.length}} registros</strong><button @click="create">+ Nuevo quiebre</button></header><p v-if="error" class="flash badmsg">{{error}}</p><p v-if="success" class="flash okmsg">{{success}}</p><section class="filters"><input v-model.trim="search" placeholder="Buscar por código, nombre o padre"><select v-model="level"><option value="">Todos los niveles</option><option value="1">Nivel 1</option><option value="2">Nivel 2</option><option value="3">Nivel 3</option></select><button class="soft" @click="search='';level=''">Limpiar</button></section><section class="card"><div v-if="loading" class="empty">Procesando…</div><div v-else-if="!filtered.length" class="empty">No hay quiebres registrados.</div><div v-else class="scroll"><table><thead><tr><th>Orden</th><th>Nivel</th><th>Código</th><th>Nombre</th><th>Padre</th><th>Movimiento</th><th>Estado</th><th>Acciones</th></tr></thead><tbody><tr v-for="item in filtered" :key="item.id"><td>{{item.orden}}</td><td><span class="level">N{{item.nivel}}</span></td><td><b>{{item.codigo}}</b></td><td :style="{paddingLeft:`${10+(item.nivel-1)*18}px`}">{{item.nombre}}</td><td>{{item.padre?.codigo}} · {{item.padre?.nombre||'-'}}</td><td><span v-if="item.tipo_movimiento" :class="item.tipo_movimiento==='INGRESO'?'income':'expense'">{{item.tipo_movimiento}}</span><span v-else>-</span></td><td><span :class="item.activo?'good':'bad'">{{item.activo?'ACTIVO':'INACTIVO'}}</span></td><td class="actions"><button class="edit" @click="edit(item)">Editar</button><button :class="item.activo?'danger':'activate'" @click="toggle(item)">{{item.activo?'Inactivar':'Activar'}}</button></td></tr></tbody></table></div></section><div v-if="showForm" class="backdrop" @mousedown.self="showForm=false"><form class="dialog" @submit.prevent="save"><header><div><small>{{editing?'EDICIÓN':'NUEVO REGISTRO'}}</small><h2>{{editing?'Editar':'Registrar'}} quiebre</h2></div><button type="button" @click="showForm=false">×</button></header><div class="twocol"><label>Nivel<select v-model.number="form.nivel" required><option :value="1">Nivel 1</option><option :value="2">Nivel 2</option><option :value="3">Nivel 3</option></select></label><label>Quiebre padre<select v-model="form.padre_id" :disabled="form.nivel===1" :required="form.nivel>1"><option :value="null">{{form.nivel===1?'No corresponde':'Seleccione'}}</option><option v-for="x in availableParents" :key="x.id" :value="x.id">N{{x.nivel}} · {{x.codigo}} · {{x.nombre}}</option></select></label></div><div class="twocol"><label>Código<input v-model.trim="form.codigo" maxlength="20" required></label><label>Orden<input v-model.number="form.orden" type="number" min="0" step="1"></label></div><label>Nombre<input v-model.trim="form.nombre" maxlength="150" required></label><label>Tipo de movimiento<select v-model="form.tipo_movimiento"><option value="">Sin clasificación</option><option value="INGRESO">Ingreso</option><option value="EGRESO">Egreso</option></select></label><footer><button type="button" class="soft" @click="showForm=false">Cancelar</button><button :disabled="loading">Guardar</button></footer></form></div></div></template>
<style scoped>
.page{--a:#176d78;color:#344750}nav{margin-bottom:15px;color:#91a0a5;font-size:.68rem}nav a{color:var(--a)}.hero{display:flex;align-items:center;gap:14px;padding:20px;border-left:5px solid var(--a);border-radius:12px;background:#fff}.mark{width:50px;height:50px;display:grid;place-items:center;border-radius:10px;color:#fff;background:var(--a);font-weight:800}.hero>div:nth-child(2){flex:1}.hero small,.dialog small{color:var(--a);font-size:.49rem;font-weight:800}.hero h1{margin:3px 0;font-size:1.3rem}.hero p{margin:0;color:#7c8b91;font-size:.65rem}.hero strong{font-size:.55rem}button{padding:8px 11px;border:0;border-radius:6px;color:#fff;background:var(--a);font-size:.5rem;cursor:pointer}.soft{color:#607078;background:#edf2f3}.flash{padding:10px;border-radius:6px;font-size:.55rem}.badmsg{color:#9b3d48;background:#fdebee}.okmsg{color:#236c50;background:#e8f7ee}.filters{margin-top:11px;padding:13px;display:grid;grid-template-columns:2fr 1fr auto;gap:7px;background:#fff}.filters input,.filters select,.dialog input,.dialog select{box-sizing:border-box;width:100%;padding:9px;border:1px solid #d5dfe2;border-radius:6px;background:#fff;font-size:.5rem}.card{margin-top:11px;background:#fff}.scroll{overflow:auto}table{width:100%;min-width:950px;border-collapse:collapse;font-size:.49rem}th,td{padding:10px;border-bottom:1px solid #e3e9eb;text-align:left}th{color:#fff;background:#435d6c}.level,.good,.bad,.income,.expense{padding:4px 8px;border-radius:10px;font-size:.42rem;font-weight:800}.level{color:#3b6273;background:#e8f2f6}.good,.income{color:#267153;background:#e5f7ec}.bad,.expense{color:#9d414a;background:#fdebed}.actions{display:flex;gap:5px}.edit{background:#c98a24}.danger{background:#b74b54}.activate{background:#27875f}.empty{padding:50px;text-align:center}.backdrop{position:fixed;z-index:100;inset:0;padding:20px;display:grid;place-items:center;background:#172b3d88}.dialog{width:min(630px,100%);padding:20px;box-sizing:border-box;border-radius:12px;background:#fff}.dialog>header{display:flex}.dialog>header div{flex:1}.dialog h2{margin:3px 0 15px}.dialog>header button{color:#66757b;background:none;font-size:1.2rem}.dialog label{display:grid;gap:5px;margin:10px 0;font-size:.52rem;font-weight:700}.twocol{display:grid;grid-template-columns:1fr 1fr;gap:10px}.dialog footer{display:flex;justify-content:center;gap:8px;margin-top:15px}@media(max-width:650px){.filters,.twocol{grid-template-columns:1fr}.hero{flex-wrap:wrap}.mark{display:none}}
</style>
